import{_ as t,c as s,o,a2 as a}from"./chunks/framework.DkPtUiZm.js";const h=JSON.parse('{"title":"Mouvement et finition","description":"","frontmatter":{},"headers":[],"relativePath":"fondations/mouvement.md","filePath":"fondations/mouvement.md","lastUpdated":1790233006000}'),i={name:"fondations/mouvement.md"};function d(n,e,r,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="mouvement-et-finition" tabindex="-1">Mouvement et finition <a class="header-anchor" href="#mouvement-et-finition" aria-label="Permalink to &quot;Mouvement et finition&quot;">​</a></h1><h2 id="le-probleme" tabindex="-1">Le problème <a class="header-anchor" href="#le-probleme" aria-label="Permalink to &quot;Le problème&quot;">​</a></h2><p>Les composants paraissaient plats, et ce n&#39;était pas une impression. Le dépôt n&#39;avait <strong>aucun token de mouvement</strong> : les durées étaient écrites à la main, <code>.15s</code> ici, <code>.12s</code> là, sans que rien ne relie les deux. Aucune occurrence de <code>prefers-reduced-motion</code>.</p><p>Le bouton résumait le problème. Il déclarait une transition sur trois propriétés, puis <strong>n&#39;écrivait aucune règle <code>:hover</code> ni <code>:active</code></strong> : il n&#39;y avait rien à animer. La transition était déclarée dans le vide.</p><h2 id="les-tokens" tabindex="-1">Les tokens <a class="header-anchor" href="#les-tokens" aria-label="Permalink to &quot;Les tokens&quot;">​</a></h2><p><code>@sia-ui/tokens</code> expose trois familles de plus.</p><table tabindex="0"><thead><tr><th>Token</th><th>Valeur</th><th>Rôle</th></tr></thead><tbody><tr><td><code>duration.instant</code></td><td>80 ms</td><td>retour tactile — <code>:active</code>, bascule d&#39;une case</td></tr><tr><td><code>duration.fast</code></td><td>120 ms</td><td>survol, focus, changement de couleur</td></tr><tr><td><code>duration.base</code></td><td>180 ms</td><td>ouverture d&#39;un popover, d&#39;un accordéon</td></tr><tr><td><code>duration.slow</code></td><td>260 ms</td><td>modale, drawer</td></tr><tr><td><code>easing.standard</code></td><td><code>cubic-bezier(.2,.7,.3,1)</code></td><td>défaut, décélération marquée</td></tr><tr><td><code>easing.entrance</code></td><td><code>cubic-bezier(0,.55,.45,1)</code></td><td>apparition d&#39;une couche</td></tr><tr><td><code>easing.exit</code></td><td><code>cubic-bezier(.4,0,1,1)</code></td><td>disparition, plus rapide que l&#39;entrée</td></tr><tr><td><code>easing.spring</code></td><td><code>cubic-bezier(.34,1.56,.64,1)</code></td><td>rebond léger — switch, note</td></tr><tr><td><code>elevation.rest / hover / press</code></td><td>trois ombres</td><td>états d&#39;un contrôle</td></tr><tr><td><code>elevation.overlay / modal</code></td><td>deux ombres</td><td>couches flottantes</td></tr></tbody></table><p><strong>Un composant ne choisit plus une durée, il choisit un rôle.</strong></p><h2 id="une-seule-source-pour-le-theme" tabindex="-1">Une seule source pour le thème <a class="header-anchor" href="#une-seule-source-pour-le-theme" aria-label="Permalink to &quot;Une seule source pour le thème&quot;">​</a></h2><p>Le bloc <code>:root</code> de la feuille de style était recopié à la main : changer une couleur demandait de la modifier à deux endroits, et rien ne signalait quand les deux divergeaient.</p><p>Il est désormais <strong>généré</strong> depuis <code>@sia-ui/tokens</code> :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @sia-ui/react-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:theme</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # réécrit le bloc</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @sia-ui/react-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:theme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # échoue s&#39;il a dérivé</span></span></code></pre></div><p>Le <code>--check</code> tourne dans <strong><code>build</code></strong>, pas dans <code>typecheck</code> : le script lit les tokens <em>compilés</em>, et seul <code>build</code> attend que ses dépendances le soient. Faire attendre <code>typecheck</code> coûterait un build complet pour vérifier des types.</p><p>Le thème sombre arrive avec : il suit <code>prefers-color-scheme</code>, sauf choix explicite via <code>data-sia-color-mode</code>.</p><p>Deux pièges rencontrés en posant ce mécanisme, l&#39;un et l&#39;autre invisibles en local :</p><ul><li>le script lisait <code>@sia-ui/tokens</code> avant que le paquet ne soit construit. Chez moi un <code>dist</code> traînait d&#39;une exécution précédente; en CI, non;</li><li>il écrivait en <code>LF</code> dans un fichier en <code>CRLF</code>, donc <code>--check</code> signalait une dérive à chaque aller-retour Windows/Linux. Le script respecte désormais la convention du fichier, et un <code>.gitattributes</code> normalise le dépôt en <code>LF</code>.</li></ul><h2 id="la-couche-de-mouvement" tabindex="-1">La couche de mouvement <a class="header-anchor" href="#la-couche-de-mouvement" aria-label="Permalink to &quot;La couche de mouvement&quot;">​</a></h2><p><code>src/styles/shared.css</code> porte ce que les composants réutilisent :</p><ul><li><code>sia-fade-in</code>, <code>sia-scale-in</code>, <code>sia-slide-up</code> — les entrées de couches;</li><li><code>.sia-transition-colors</code>, <code>.sia-transition-lift</code> — les transitions courantes;</li><li>un anneau de focus unique, sur <code>:where(button, a, input, …):focus-visible</code>;</li><li><strong>le repli <code>prefers-reduced-motion</code></strong>, qui ramène tout à <code>0.01ms</code>.</li></ul><p>Ce dernier n&#39;est pas un confort : c&#39;est une demande médicale pour les personnes sujettes aux vertiges vestibulaires. Il ne souffre aucune exception.</p><h2 id="les-icones" tabindex="-1">Les icônes <a class="header-anchor" href="#les-icones" aria-label="Permalink to &quot;Les icônes&quot;">​</a></h2><p>Cinq caractères servaient d&#39;icônes dans sept composants :</p><table tabindex="0"><thead><tr><th>Caractère</th><th>Où</th><th>Remplacé par</th></tr></thead><tbody><tr><td><code>×</code> U+00D7</td><td>alert, modal, multi-select, search-input, select, tags-input</td><td><code>XIcon</code></td></tr><tr><td><code>⌄</code> U+2304</td><td>select — le chevron</td><td><code>ChevronDownIcon</code></td></tr><tr><td><code>✓</code> U+2713</td><td>select — l&#39;option choisie</td><td><code>CheckIcon</code></td></tr><tr><td><code>⌕</code> U+2315</td><td>select, search-input</td><td><code>SearchIcon</code></td></tr><tr><td><code>★</code> U+2605</td><td>rating</td><td><code>StarIcon</code></td></tr></tbody></table><p>Un glyphe hérite de la police du système : il ne se dimensionne pas en <code>em</code>, ne prend pas d&#39;épaisseur de trait, ne tourne pas autour d&#39;un centre prévisible, et <code>⌕</code> s&#39;affiche en carré vide sur beaucoup de machines. Le chevron du Select avait d&#39;ailleurs déjà été rafistolé <strong>deux fois</strong> en CSS pour compenser son décalage de ligne de base.</p><p><code>Icons</code> compte désormais <strong>20 tracés</strong>. Le chevron du Select tourne de 180° à l&#39;ouverture — impossible avec un caractère, puisque son centre de rotation dépendait de la fonte.</p><p><code>Rating</code> gagne au passage la <strong>demi-étoile</strong> : deux tracés superposés, celui du dessus rogné par <code>clip-path</code> à la part remplie. Structurellement impossible avec <code>★</code>.</p><h2 id="ce-qui-a-bouge-composant-par-composant" tabindex="-1">Ce qui a bougé, composant par composant <a class="header-anchor" href="#ce-qui-a-bouge-composant-par-composant" aria-label="Permalink to &quot;Ce qui a bougé, composant par composant&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Composant</th><th>Ce qui change</th></tr></thead><tbody><tr><td><code>Button</code>, <code>IconButton</code></td><td>prop <code>tone</code>, dégradé d&#39;un degré, élévation de 1 px au survol, enfoncement à l&#39;appui</td></tr><tr><td><code>Select</code></td><td>chevron SVG qui pivote, panneau en <code>scale + fade</code></td></tr><tr><td><code>Modal</code>, <code>Popover</code></td><td>entrée animée, ombre de couche</td></tr><tr><td><code>Drawer</code></td><td>durées passées en tokens, sortie sur <code>easing.exit</code></td></tr><tr><td><code>Switch</code>, <code>Checkbox</code></td><td><code>easing.spring</code> sur le pouce et la coche, écrasement à l&#39;appui</td></tr><tr><td><code>Tabs</code></td><td>indicateur qui glisse sous l&#39;onglet actif</td></tr><tr><td><code>Rating</code></td><td>demi-étoile, agrandissement au survol</td></tr><tr><td><code>DataTable</code></td><td>lignes réactives au survol et à la sélection</td></tr></tbody></table><h2 id="le-dosage-de-l-ombre" tabindex="-1">Le dosage de l&#39;ombre <a class="header-anchor" href="#le-dosage-de-l-ombre" aria-label="Permalink to &quot;Le dosage de l&#39;ombre&quot;">​</a></h2><p>Premier jet trop appuyé : le bouton plein empilait <code>elevation.hover</code> — qui compte déjà deux couches — <strong>et</strong> un halo coloré de 18 px. Quatre ombres pour un survol.</p><p>Deux corrections :</p><ul><li><code>elevation.hover</code> est passée de <code>0 2px 4px /.08, 0 8px 18px /.10</code> à <code>0 1px 2px /.06, 0 3px 8px /.07</code>;</li><li>le bouton plein ne porte plus <strong>qu&#39;une seule ombre</strong>, teintée par son ton. Sur une surface colorée, une ombre neutre empilée sur une ombre colorée ne fait qu&#39;épaissir la tache sans rien ajouter.</li></ul><p>Le survol garde son élévation d&#39;un pixel; c&#39;est le déplacement qui signale la réaction, pas la taille de l&#39;ombre.</p><p>Cette retouche a révélé un défaut sans rapport : cinq composants — <code>Calendar</code>, <code>DatePicker</code>, <code>DateRangePicker</code>, <code>TimePicker</code>, <code>TimeRangePicker</code> — importaient <code>@sia-ui/react-web</code>, c&#39;est-à-dire <strong>leur propre paquet</strong> : leur <code>./icons</code> avait été redirigé vers le paquet avant qu&#39;ils n&#39;y entrent eux-mêmes. Ils pointent désormais sur <code>../Icons</code>, et les dépendances du registre sont régénérées depuis les imports réels plutôt que tenues à la main.</p><h2 id="la-prop-tone" tabindex="-1">La prop <code>tone</code> <a class="header-anchor" href="#la-prop-tone" aria-label="Permalink to &quot;La prop `tone`&quot;">​</a></h2><p><code>.sia-button--danger</code> existait dans la feuille de style <strong>sans qu&#39;aucune prop ne permette de l&#39;atteindre</strong> : une action de suppression ne pouvait pas être rouge sans un <code>className</code> manuel.</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Button</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;danger&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Supprimer&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Button</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;success&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> variant</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;outline&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Valider&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Chaque ton ne fixe qu&#39;une variable, <code>--sia-button-accent</code>; les trois variantes s&#39;y réfèrent. Ajouter un ton, c&#39;est une ligne.</p><h2 id="voir-le-resultat" tabindex="-1">Voir le résultat <a class="header-anchor" href="#voir-le-resultat" aria-label="Permalink to &quot;Voir le résultat&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> storybook</span></span></code></pre></div><p>La story <strong>Fondations / Motion</strong> montre les tons, le ressort, les durées à l&#39;échelle et les élévations.</p>',41)])])}const m=t(i,[["render",d]]);export{h as __pageData,m as default};
